import React from 'react';

export function CommentView({ comment }) {
  // XSS 공격을 방지하기 위해 DOMPurify 라이브러리를 사용하여 사용자 입력을 제한적으로 허용
  const sanitizedComment = DOMPurify.sanitize(comment);
  return (
    <div className="comment">
      <h3>User said:</h3>
      <div dangerouslySetInnerHTML={{ __html: sanitizedComment }} />
    </div>
  );
}
```
한줄 요약: DOMPurify 라이브러리를 사용하여 사용자 입력을 제한적으로 허용하여 XSS 공격을 방지합니다.
